def lookup_class(
    kind: str, apiVersion: Optional[str] = None, default: Optional[str] = "__main__"
) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className, default)
    except ImportError:
        klass = None

    if klass:
        register_class(className, klass)
    return klass
